use std::fmt::Write;

use crate::model::State;

pub fn render_markdown(state: &State) -> String {
    let mut out = String::new();

    out.push_str("# Current Task State\n\n");
    out.push_str(
        "> *Auto-generated by `evedoo-taskstate` from `docs/agent-state/tasks.jsonl`. Do not edit manually.*\n\n",
    );

    // Active Phase
    out.push_str("## Active Phase\n\n");
    if let Some(phase) = &state.active_phase {
        let _ = writeln!(out, "- **Phase**: {}", phase.phase);
        let _ = writeln!(out, "- **Title**: {}", phase.title);
        let _ = writeln!(out, "- **Goal**: {}", phase.goal);
        let _ = writeln!(
            out,
            "- **Opened**: {} (by `{}`)",
            phase.opened_at.format("%Y-%m-%d %H:%M:%S UTC"),
            phase.opened_by.runtime
        );
    } else {
        out.push_str("*No active phase*\n");
    }
    out.push('\n');

    // In Progress
    out.push_str("## In Progress\n\n");
    if state.in_progress.is_empty() {
        out.push_str("*None*\n");
    } else {
        for t in &state.in_progress {
            let runtime_str = t
                .by
                .as_ref()
                .map(|a| a.runtime.as_str())
                .unwrap_or("unknown");
            let time_str = t
                .updated_at
                .map(|ts| ts.format("%Y-%m-%d %H:%M:%S UTC").to_string())
                .unwrap_or_default();
            let _ = writeln!(
                out,
                "- **{}**: {} (started by `{}` at {})",
                t.task, t.title, runtime_str, time_str
            );
            if let Some(note) = &t.note {
                let _ = writeln!(out, "  - Note: {}", note);
            }
        }
    }
    out.push('\n');

    // In Review (if any)
    if !state.in_review.is_empty() {
        out.push_str("## In Review\n\n");
        for t in &state.in_review {
            let runtime_str = t
                .by
                .as_ref()
                .map(|a| a.runtime.as_str())
                .unwrap_or("unknown");
            let time_str = t
                .updated_at
                .map(|ts| ts.format("%Y-%m-%d %H:%M:%S UTC").to_string())
                .unwrap_or_default();
            let _ = writeln!(
                out,
                "- **{}**: {} (submitted by `{}` at {})",
                t.task, t.title, runtime_str, time_str
            );
            if let Some(summary) = &t.summary {
                let _ = writeln!(out, "  - Summary: {}", summary);
            }
            if let Some(verdict) = &t.verdict {
                let _ = writeln!(out, "  - Last Verdict: {:?}", verdict);
            }
            if let Some(note) = &t.note {
                let _ = writeln!(out, "  - Review Note: {}", note);
            }
        }
        out.push('\n');
    }

    // Pending Handoff
    out.push_str("## Pending Handoff\n\n");
    if let Some(h) = &state.pending_handoff {
        let _ = writeln!(
            out,
            "- **To**: `{}` (from `{}` at {})",
            h.to,
            h.from,
            h.at.format("%Y-%m-%d %H:%M:%S UTC")
        );
        if let Some(task) = &h.task {
            let _ = writeln!(out, "- **Task**: {}", task);
        }
        let _ = writeln!(out, "- **Reason**: {}", h.reason);
        if let Some(note) = &h.note {
            let _ = writeln!(out, "- **Note**: {}", note);
        }
    } else {
        out.push_str("*None*\n");
    }
    out.push('\n');

    // Next Task
    out.push_str("## Next Task\n\n");
    if let Some(next) = &state.next {
        let _ = writeln!(out, "- **{}**: {}", next.task, next.title);
        let _ = writeln!(out, "  - Phase: {}", next.phase);
        if !next.depends_on.is_empty() {
            let _ = writeln!(out, "  - Depends on: {}", next.depends_on.join(", "));
        }
        if let Some(desc) = &next.description {
            let _ = writeln!(out, "  - Description: {}", desc);
        }
    } else {
        out.push_str("*None*\n");
    }
    out.push('\n');

    // Last Done
    out.push_str("## Last Done\n\n");
    if let Some(last) = &state.last_done {
        let runtime_str = last
            .by
            .as_ref()
            .map(|a| a.runtime.as_str())
            .unwrap_or("unknown");
        let closed_str = last
            .closed_at
            .map(|ts| ts.format("%Y-%m-%d %H:%M:%S UTC").to_string())
            .unwrap_or_default();
        let _ = writeln!(out, "- **{}**: {}", last.task, last.title);
        let _ = writeln!(out, "  - Phase: {}", last.phase);
        let _ = writeln!(out, "  - Closed: {} (by `{}`)", closed_str, runtime_str);
        if let Some(summary) = &last.summary {
            let _ = writeln!(out, "  - Summary: {}", summary);
        }
    } else {
        out.push_str("*None*\n");
    }
    out.push('\n');

    // Recent Rulings
    out.push_str("## Recent Rulings\n\n");
    if state.recent_rulings.is_empty() {
        out.push_str("*None*\n");
    } else {
        for r in &state.recent_rulings {
            let _ = writeln!(out, "- **{}**", r.subject);
            let _ = writeln!(out, "  - Decision: {}", r.decision);
            let _ = writeln!(out, "  - Rationale: {}", r.rationale);
            let _ = writeln!(out, "  - Cost if wrong: {}", r.cost_if_wrong);
            let _ = writeln!(
                out,
                "  - Recorded by: `{}` at {}",
                r.by.runtime,
                r.at.format("%Y-%m-%d %H:%M:%S UTC")
            );
        }
    }
    out.push('\n');

    // Recently Closed Tasks
    out.push_str("## Recently Closed Tasks\n\n");
    if state.recently_closed.is_empty() {
        out.push_str("*None*\n");
    } else {
        for t in &state.recently_closed {
            let closed_str = t
                .closed_at
                .map(|ts| ts.format("%Y-%m-%d %H:%M:%S UTC").to_string())
                .unwrap_or_default();
            let _ = writeln!(out, "- **{}**: {} (closed {})", t.task, t.title, closed_str);
        }
    }

    out
}

#[cfg(test)]
mod tests {
    use chrono::{DateTime, Utc};

    use super::*;
    use crate::model::*;

    fn dt(s: &str) -> DateTime<Utc> {
        s.parse::<DateTime<Utc>>().unwrap()
    }

    #[test]
    fn test_render_empty_state() {
        let state = State::default();
        let md = render_markdown(&state);
        assert!(md.contains("# Current Task State"));
        assert!(md.contains("## Active Phase\n\n*No active phase*"));
        assert!(md.contains("## In Progress\n\n*None*"));
        assert!(md.contains("## Pending Handoff\n\n*None*"));
        assert!(md.contains("## Next Task\n\n*None*"));
        assert!(md.contains("## Last Done\n\n*None*"));
        assert!(md.contains("## Recent Rulings\n\n*None*"));
        assert!(md.contains("## Recently Closed Tasks\n\n*None*"));
    }

    #[test]
    fn test_render_populated_state() {
        let state = State {
            active_phase: Some(PhaseSummary {
                phase: "P20".to_string(),
                title: "Operationalisation".to_string(),
                goal: "All tests green".to_string(),
                opened_at: dt("2026-08-28T01:00:00Z"),
                opened_by: Actor::new("antigravity"),
            }),
            in_progress: vec![TaskSummary {
                task: "P20-T1".to_string(),
                phase: "P20".to_string(),
                title: "Task 1".to_string(),
                description: None,
                depends_on: vec![],
                review_required: true,
                status: TaskStatus::InProgress,
                by: Some(Actor::new("antigravity")),
                outcome: None,
                verdict: None,
                summary: None,
                note: Some("Working on registry".to_string()),
                commit: None,
                concerns: vec![],
                updated_at: Some(dt("2026-08-28T01:10:00Z")),
                closed_at: None,
            }],
            in_review: vec![],
            next: Some(TaskSummary {
                task: "P20-T2".to_string(),
                phase: "P20".to_string(),
                title: "Task 2".to_string(),
                description: Some("Second task".to_string()),
                depends_on: vec!["P20-T1".to_string()],
                review_required: true,
                status: TaskStatus::Declared,
                by: Some(Actor::new("antigravity")),
                outcome: None,
                verdict: None,
                summary: None,
                note: None,
                commit: None,
                concerns: vec![],
                updated_at: Some(dt("2026-08-28T01:05:00Z")),
                closed_at: None,
            }),
            last_done: Some(TaskSummary {
                task: "P19-T5".to_string(),
                phase: "P19".to_string(),
                title: "Prev Task".to_string(),
                description: None,
                depends_on: vec![],
                review_required: true,
                status: TaskStatus::Closed,
                by: Some(Actor::new("claude-code")),
                outcome: Some(Outcome::Done),
                verdict: Some(Verdict::Clean),
                summary: Some("Completed previous task".to_string()),
                note: None,
                commit: None,
                concerns: vec![],
                updated_at: Some(dt("2026-08-28T00:50:00Z")),
                closed_at: Some(dt("2026-08-28T00:50:00Z")),
            }),
            pending_handoff: Some(HandoffSummary {
                from: "claude-code".to_string(),
                to: "antigravity".to_string(),
                task: Some("P20-T1".to_string()),
                reason: "Needs non-claude review".to_string(),
                note: Some("Check memory".to_string()),
                at: dt("2026-08-28T01:08:00Z"),
            }),
            recent_rulings: vec![RulingSummary {
                subject: "Migration Ruling".to_string(),
                decision: "In-place".to_string(),
                rationale: "Zero-copy".to_string(),
                cost_if_wrong: "Rollback".to_string(),
                by: Actor::new("claude-code"),
                at: dt("2026-08-28T00:30:00Z"),
            }],
            recently_closed: vec![TaskSummary {
                task: "P19-T5".to_string(),
                phase: "P19".to_string(),
                title: "Prev Task".to_string(),
                description: None,
                depends_on: vec![],
                review_required: true,
                status: TaskStatus::Closed,
                by: Some(Actor::new("claude-code")),
                outcome: Some(Outcome::Done),
                verdict: Some(Verdict::Clean),
                summary: Some("Completed previous task".to_string()),
                note: None,
                commit: None,
                concerns: vec![],
                updated_at: Some(dt("2026-08-28T00:50:00Z")),
                closed_at: Some(dt("2026-08-28T00:50:00Z")),
            }],
            all_tasks: vec![],
            store_path: None,
        };

        let md = render_markdown(&state);
        assert!(md.contains("Phase**: P20"));
        assert!(md.contains("P20-T1**: Task 1 (started by `antigravity`"));
        assert!(md.contains("Note: Working on registry"));
        assert!(md.contains("To**: `antigravity` (from `claude-code`"));
        assert!(md.contains("Task**: P20-T1"));
        assert!(md.contains("Reason**: Needs non-claude review"));
        assert!(md.contains("Next Task\n\n- **P20-T2**: Task 2"));
        assert!(md.contains("Depends on: P20-T1"));
        assert!(md.contains("Last Done\n\n- **P19-T5**: Prev Task"));
        assert!(md.contains("Migration Ruling"));
        assert!(md.contains("Decision: In-place"));
    }
}
